script:
class Component extends DCLogic {
state = { title: '', price: '', imageUrl: '', previewUrl: '', imageError: false, uploading: false, products: [], error: '', listError: '', notice: '' };
mount() {
  document.addEventListener('error', (event) => {
    if (event.target && event.target.id === 'product-image-preview') this.setState({ imageError: true });
  }, true);
  this.loadProducts();
}
loadProducts() {
  const api = parent.SONNA_API;
  if (!api) return this.setState({ listError: 'KhÃ´ng káº¿t ná»‘i Ä‘Æ°á»£c mÃ¡y chá»§.' });
  api('GET', '/api/products').then((result) => {
    if (result._status !== 200 || !Array.isArray(result.products)) return this.setState({ listError: result.error || 'KhÃ´ng táº£i Ä‘Æ°á»£c sáº£n pháº©m.' });
    this.setState({ products: result.products, listError: '' });
  }).catch(() => this.setState({ listError: 'Lá»—i káº¿t ná»‘i mÃ¡y chá»§.' }));
}
onTitle(event) { this.setState({ title: event.target.value, error: '', notice: '' }); }
onPrice(event) { this.setState({ price: event.target.value, error: '', notice: '' }); }
onImageUrl(event) {
  const imageUrl = event.target.value.trim();
  let previewUrl = '';
  try { const url = new URL(imageUrl); if (url.protocol === 'https:' && !url.username && !url.password) previewUrl = url.href; } catch (error) {}
  this.setState({ imageUrl, previewUrl, imageError: false, error: '', notice: '' });
}
onImageFile(event) {
  const file = event.target.files && event.target.files[0];
  event.target.value = '';
  if (!file) return;
  if (!['image/jpeg', 'image/png', 'image/webp', 'image/gif'].includes(file.type) || file.size > 4 * 1024 * 1024) {
    return this.setState({ error: 'Ch\u1ec9 nh\u1eadn JPG, PNG, WebP ho\u1eb7c GIF t\u1ed1i \u0111a 4 MB.', notice: '' });
  }
  this.setState({ uploading: true, error: '', notice: '' });
  const reader = new FileReader();
  reader.onerror = () => this.setState({ uploading: false, error: 'Kh\u00f4ng th\u1ec3 \u0111\u1ecdc file \u1ea3nh.', notice: '' });
  reader.onload = () => {
    const api = parent.SONNA_API;
    if (!api) return this.setState({ uploading: false, error: 'Kh\u00f4ng k\u1ebft n\u1ed1i \u0111\u01b0\u1ee3c m\u00e1y ch\u1ee7.', notice: '' });
    api('POST', '/api/admin/upload', { dataUrl: String(reader.result || '') }).then((result) => {
      if (result._status !== 200 || !result.url) return this.setState({ uploading: false, error: result.error || 'T\u1ea3i \u1ea3nh l\u00ean Supabase th\u1ea5t b\u1ea1i.', notice: '' });
      this.setState({ uploading: false, imageUrl: result.url, previewUrl: result.url, imageError: false, error: '', notice: '\u1ea2nh \u0111\u00e3 l\u01b0u tr\u00ean Supabase. B\u1ea5m L\u01b0u s\u1ea3n ph\u1ea9m \u0111\u1ec3 ho\u00e0n t\u1ea5t.' });
    }).catch(() => this.setState({ uploading: false, error: 'L\u1ed7i k\u1ebft n\u1ed1i khi t\u1ea3i \u1ea3nh l\u00ean Supabase.', notice: '' }));
  };
  reader.readAsDataURL(file);
}
onRefresh() { this.loadProducts(); }
onSubmit(event) {
  event.preventDefault();
  const title = this.state.title.trim();
  const price = this.state.price.trim() ? Number(this.state.price) : NaN;
  const imageUrl = this.state.imageUrl.trim();
  let validImage = false;
  try { const url = new URL(imageUrl); validImage = url.protocol === 'https:' && !url.username && !url.password; } catch (error) {}
  if (!title || title.length > 200) return this.setState({ error: 'Nháº­p tÃªn sáº£n pháº©m (tá»‘i Ä‘a 200 kÃ½ tá»±).' });
  if (!Number.isFinite(price) || price < 0 || price > 9999999999.99) return this.setState({ error: 'Nháº­p giÃ¡ há»£p lá»‡ tá»« 0 Ä‘áº¿n 9.999.999.999,99.' });
  if (!validImage) return this.setState({ error: 'Nháº­p URL áº£nh HTTPS há»£p lá»‡.' });
  const api = parent.SONNA_API;
  if (!api) return this.setState({ error: 'KhÃ´ng káº¿t ná»‘i Ä‘Æ°á»£c mÃ¡y chá»§.' });
  api('POST', '/api/products', { title, price, imageUrl }).then((result) => {
    if (result._status !== 201) return this.setState({ error: result.error || (result._status === 401 ? 'PhiÃªn admin Ä‘Ã£ háº¿t háº¡n. HÃ£y Ä‘Äƒng nháº­p láº¡i.' : 'KhÃ´ng lÆ°u Ä‘Æ°á»£c sáº£n pháº©m.'), notice: '' });
    this.setState({ title: '', price: '', imageUrl: '', previewUrl: '', imageError: false, error: '', notice: 'ÄÃ£ lÆ°u sáº£n pháº©m vÃ o PostgreSQL.' });
    this.loadProducts();
  }).catch(() => this.setState({ error: 'Lá»—i káº¿t ná»‘i mÃ¡y chá»§ khi lÆ°u sáº£n pháº©m.', notice: '' }));
}
renderVals() {
  const products = this.state.products.map((product) => ({
    title: product.title,
    imageUrl: product.imageUrl,
    priceLabel: Number(product.price).toLocaleString('vi-VN') + ' â‚«'
  }));
  return {
    title: this.state.title,
    price: this.state.price,
    imageUrl: this.state.imageUrl,
    previewUrl: this.state.previewUrl,
    hasPreview: !!this.state.previewUrl && !this.state.imageError,
    isImageError: this.state.imageError,
    uploadingLabel: this.state.uploading ? '\u0110ang t\u1ea3i \u1ea3nh l\u00ean Supabase...' : '',
    products,
    count: String(products.length),
    error: this.state.error,
    listError: this.state.listError,
    notice: this.state.notice,
    onTitle: (event) => this.onTitle(event),
    onPrice: (event) => this.onPrice(event),
    onImageUrl: (event) => this.onImageUrl(event),
    onRefresh: () => this.onRefresh(),
    onSubmit: (event) => this.onSubmit(event)
  };
}
}
